item.command:
/bin/zsh -lc "python3 - <<'PY'
from huggingface_hub import hf_hub_download
files=['synthetic_tasks/skill_based/easy/data_processing/data_filtered.parquet','dataset_adapters/code.parquet','dataset_adapters/swe.parquet']
for f in files:
  try:
    p=hf_hub_download(repo_id='nvidia/Nemotron-Terminal-Corpus', repo_type='dataset', filename=f, local_dir='/tmp/hf_nemotron', local_dir_use_symlinks=False)
    print(f, p)
  except Exception as e:
    print('ERR', f, type(e).__name__, str(e)[:300])
PY"

